/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parseElection } from './parse.js'
import { count } from './count.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  fail('error: usage: cli.js rounds|tally')
}
const mode = args[0]

let election
try {
  election = parseElection(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.isParseError) fail(e.message)
  throw e
}

const { rounds, winner } = count(election)
let out = ''
